# -*- coding: utf-8 -*-
# Testi sostitutivi (paragrafi 4.1-5.6) con grassetti secondo la convenzione della dispensa
ATL = "Per il ripasso visivo vedi l'Atlante illustrativo: "
CHAPTERS = [
 ("Capitolo 4: Il Quattrocento: Volgarizzamenti, Crisi del Volgare e Umanesimo Volgare", [
  ("4.1 I Volgarizzamenti e la Prosa Minore del Trecento",
   ATL+"Tav. 24 (dispense p. 232, Atlante p. 13).",
   "Nel Trecento il toscano si espande fuori dalla Toscana perché <b>Dante</b>, <b>Petrarca</b> e <b>Boccaccio</b> sono letti e imitati in tutta Italia. Nel Cinquecento i grammatici, <b>Bembo</b> in testa, fissano quella lingua come modello e la canonizzano in regole rigide, affiancando alle <b>Tre Corone</b> anche autori minori dello stesso secolo, ritenuto aureo perché si credeva realizzato un connubio tra scrittori e popolo. La prosa minore (<b>volgarizzamenti</b>, <b>vite dei santi</b>) è scritta in stile semplice per chi non conosceva il latino. Questa idea di una lingua trecentesca migliore di quella moderna torna nell'Ottocento con il <b>Purismo</b> di <b>Cesari</b>, che sceglie modelli esenti da difetti nel passato. Fuori dalla Toscana i poeti si toscanizzano con ibridismo e <b>ipercorrettismo</b> (consonanti doppie dove il toscano ha la scempia), mentre la prosa conserva più della poesia l'impronta locale, come nell'antico romanesco dell'<b>Anonimo romano</b>.",
   ["Nel Trecento il toscano si espande fuori regione grazie a <b>Dante</b>, <b>Petrarca</b> e <b>Boccaccio</b>, e nel Cinquecento i grammatici lo fissano come modello rigido, affiancando alle <b>Tre Corone</b> anche autori minori di quel secolo, ritenuto aureo.",
    "La prosa minore, <b>volgarizzamenti</b> e <b>vite di santi</b>, è semplice e rivolta a chi non conosceva il latino, e l'idea di una lingua trecentesca migliore tornerà con il <b>Purismo</b> di <b>Cesari</b>.",
    "Fuori dalla Toscana i poeti si toscanizzano con <b>ipercorrettismi</b>, mentre la prosa conserva più l'impronta locale, come nell'antico romanesco dell'<b>Anonimo romano</b>."]),
  ("4.2 La Crisi del Volgare nell'Umanesimo",
   ATL+"Tav. 25 (dispense p. 238, Atlante p. 14), Tav. 27 (dispense p. 257, Atlante p. 15).",
   "<b>Petrarca</b>, iniziatore dell'<b>Umanesimo</b>, affida la parte più solida del suo messaggio al latino, sul modello di Cicerone e degli autori classici. Il confronto con i classici forma una mentalità grammaticale, poi applicata alla norma dell'italiano e alla concezione della lingua come imitazione dei modelli. La svolta umanistica produce una <b>crisi del volgare</b>: non ne arresta l'uso, ma lo scredita presso i dotti. Il latino è più nobile e garantisce l'immortalità, il volgare è accettabile solo nelle scritture pratiche (esempio: <b>Salutati</b> rimpiange che <b>Dante</b> non abbia scritto la <b>Commedia</b> in latino). Le prime discussioni sull'origine del volgare nascono dalla ricerca storica sul crollo della romanità. <b>Bruni</b> giudica Dante indipendentemente dalla lingua, secondo il principio della <b>pari dignità potenziale delle lingue antiche e moderne</b>.",
   ["<b>Petrarca</b>, iniziatore dell'<b>Umanesimo</b>, affida il messaggio più solido al latino e, imitando i classici, crea una mentalità grammaticale che poi si applica anche alla norma dell'italiano.",
    "L'Umanesimo produce una <b>crisi del volgare</b>, che non scompare ma viene screditato presso i dotti: il latino è più nobile e garantisce l'immortalità, il volgare resta per le scritture pratiche, come mostra <b>Salutati</b>.",
    "Dalla ricerca storica sul crollo della romanità nascono le prime discussioni sull'origine del volgare, e <b>Bruni</b> afferma la <b>pari dignità potenziale delle lingue antiche e moderne</b>."]),
  ("4.3 Leon Battista Alberti e l'Umanesimo Volgare", None,
   "Nel Quattrocento mancava un autore di prestigio con fiducia nell'italiano, e il <b>De vulgari eloquentia</b> non era ancora noto. <b>Alberti</b> inizia l'<b>Umanesimo volgare</b>, con un programma di promozione della lingua: prosa alta nel trattato <b>Della famiglia</b> e nei volgarizzamenti. Nel Proemio al libro III riprende <b>Biondo</b> contro <b>Bruni</b>, attribuendo la perdita del latino ai barbari; ma il volgare, nato dalla barbarie, può riscattarsi facendosi ornato e copioso come il latino, grazie ai dotti. La sua prosa unisce forti latinismi sintattici e tratti popolari toscani. Gli si attribuisce la <b>Grammatichetta vaticana</b>, <b>prima grammatica di una lingua volgare moderna</b>, nata come sfida per dimostrare che anche il volgare ha una struttura ordinata. La norma è <b>l'uso</b> toscano contemporaneo, non gli autori antichi (el per il, <b>imperfetto</b> in -o). Non circolò né fu stampata; la prima grammatica a stampa è del <b>1516</b>.",
   ["<b>Alberti</b> avvia l'<b>Umanesimo volgare</b>, con un programma per elevare il volgare a lingua alta, ornata e copiosa come il latino.",
    "Riprende la tesi di <b>Biondo</b>, per cui i barbari fecero perdere il latino, ma sostiene che il volgare possa riscattarsi grazie ai dotti.",
    "La <b>Grammatichetta vaticana</b>, prima grammatica volgare, dimostra che anche il volgare ha struttura ordinata e fonda la norma sull'uso toscano contemporaneo, non sugli autori antichi."]),
  ("4.4 Lorenzo il Magnifico e la Ripresa del Volgare",
   ATL+"Tav. 26 (dispense p. 249, Atlante p. 14).",
   "Nell'età di <b>Lorenzo</b> il toscano è rilanciato con sostegno politico: Lorenzo, <b>Landino</b> e <b>Poliziano</b> promuovono il fiorentino, in una concezione patriottica del «principato della lingua», e lo ritengono comune a tutta l'Italia. Landino porta <b>Dante</b> e <b>Petrarca</b> nell'università e nega l'inferiorità del volgare. C'è anche il recupero colto di forme popolari (<b>Pulci</b> con il <b>Morgante</b> e il primo gergo in letteratura, il <b>Burchiello</b> con i doppi sensi, la novellistica toscana con i plebeismi nei dialoghi), mentre i <b>Reali di Francia</b> diffondono la prosa italiana tra un pubblico di <b>dialetto</b>. Le tradizioni regionali tendono al conguaglio verso una <b>koinè superdialettale</b>, con latinismi e appoggio al toscano, sostenuta dalle corti signorili. Il prestigio toscano cresce con la diffusione di <b>Commedia</b> e <b>Canzoniere</b> fuori dalla Toscana e con la stampa; il pubblico signorile è bilingue o trilingue (italiano, francese, latino).",
   ["Con <b>Lorenzo il Magnifico</b>, <b>Landino</b> e <b>Poliziano</b> il toscano è rilanciato con sostegno politico, nell'idea patriottica di un principato della lingua.",
    "Accanto alla letteratura alta c'è il recupero colto di forme popolari, con <b>Pulci</b>, il <b>Burchiello</b> e la novellistica toscana.",
    "Le tradizioni regionali convergono verso una <b>koinè superdialettale</b> con latinismi e appoggio al toscano, favorita dalle corti e dalla stampa."]),
 ], []),
 ("Capitolo 5: La Questione della Lingua nel Cinquecento e la Codificazione Normativa", [
  ("5.1 Pietro Bembo e la Svolta delle Prose della Volgar Lingua (1525)",
   ATL+"Tav. 28 (dispense p. 302, Atlante p. 15).",
   "Nel Cinquecento la questione della lingua si risolve nella stabilizzazione <b>normativa</b> dell'italiano. Al centro stanno le <b>Prose della volgar lingua</b> (<b>Venezia, 1525</b>), in <b>tre libri</b>: il terzo è una vera grammatica, esposta nella finzione di un dialogo ambientato nel <b>1502</b>. Bembo respinge la tesi per cui l'italiano esisteva già a Roma come lingua popolare e segue Bruni: il volgare nasce dal latino contaminato dai barbari, è una lingua nuova e può riscattarsi grazie agli scrittori. Per «volgare» intende il <b>toscano letterario trecentesco di Petrarca, Boccaccio e, in parte, Dante</b>, non il fiorentino vivo del Cinquecento: la lingua si apprende dai modelli scritti, non dal popolo. <b>Petrarca</b> è il modello per la selezione lessicale, <b>Boccaccio</b> per la sintassi latineggiante (non per i dialoghi), <b>Dante</b> solo in parte per l'eccesso di realismo. Bembo vinse perché formalizzava ciò che era già avvenuto nella prassi e perché piaceva a una classe colta devota al passato.",
   ["Nelle <b>Prose</b> del <b>1525</b> Bembo fissa la norma dell'italiano, con una grammatica nel terzo libro.",
    "Il modello è il <b>toscano letterario trecentesco</b>, <b>Petrarca</b> per il lessico e <b>Boccaccio</b> per la sintassi, appreso dagli scritti e non dal parlato.",
    "Bembo vinse perché formalizzava la prassi e rispondeva al gusto di una classe colta che poneva la perfezione nel passato."]),
  ("5.2 Le Alternative a Bembo: Speroni, Pomponazzi e le Accademie", None,
   "La proposta di Bembo non è l'unica. Nel <b>Dialogo delle lingue</b> (<b>1542</b>) <b>Sperone Speroni</b> mette in scena Bembo contro un cortegiano, sostenitore della teoria cortigiana, e contro Lazzaro Bonamico, difensore del latino. Dentro il dialogo <b>Pomponazzi</b> propone di portare la filosofia dal latino e dal greco al volgare, per modernizzare e democratizzare la cultura: una tesi troppo controcorrente. Le questioni linguistiche si discutono nelle accademie: l'<b>Accademia fiorentina</b>, dal <b>1542</b> finanziata da Cosimo de' Medici, non produce la grammatica ufficiale sperata. Dopo il <b>Concilio di Trento</b> la Chiesa diffonde il catechismo in lingua piana.",
   ["Accanto a Bembo esistono alternative, come la teoria cortigiana e la difesa del latino, messe in scena nel <b>Dialogo delle lingue</b> di <b>Speroni</b>.",
    "<b>Pomponazzi</b> propone una filosofia in volgare per democratizzare la cultura, ma resta una voce isolata.",
    "Le accademie, come quella fiorentina, discutono la lingua senza produrre la grammatica ufficiale, mentre la Chiesa dopo <b>Trento</b> usa una lingua piana nel catechismo."]),
  ("5.3 Il Ruolo della Stampa Aldina e la Nascita dei Primi Strumenti Grammaticali", None,
   "L'affermazione della norma si deve al sodalizio tra Bembo e l'editore veneziano <b>Aldo Manuzio</b>, che nel <b>1501</b> stampa il <b>Petrarca</b> curato da Bembo, in formato tascabile e con il <b>corsivo aldino</b>. Il titolo, Le cose volgari e non «vulgari», segna un taglio netto con le grafie latineggianti della koinè; compare per la prima volta l'<b>apostrofo</b>. L'aldina della <b>Commedia</b> è del <b>1502</b>. Servivano strumenti normativi: Bembo fu preceduto da <b>Fortunio</b>, che nel <b>1516</b> stampa le <b>Regole grammaticali della volgar lingua</b>, fondate sui trecentisti ma senza le riserve bembiane. Verso metà secolo grammatiche pratiche e didattiche (<b>Dolce</b> <b>1550</b>, <b>Sansovino</b> <b>1562</b>, <b>Ruscelli</b> <b>1581</b>) divulgano la lingua di Bembo.",
   ["La norma si afferma grazie alla stampa aldina, con il <b>Petrarca</b> di Bembo del <b>1501</b>, che fissa grafia e apostrofo.",
    "La prima grammatica a stampa è di <b>Fortunio</b>, del <b>1516</b>, e precede Bembo.",
    "Le grammatiche di metà secolo diffondono la lingua di Bembo a un pubblico più ampio."]),
  ("5.4 L'Accademia della Crusca e il Vocabolario del 1612",
   ATL+"Tav. 29 (dispense p. 312, Atlante p. 16).",
   "La Crusca nasce nel <b>1582</b> come passatempo di cicalate scherzose; con l'ingresso di <b>Salviati</b> (<b>1583</b>) emergono interessi filologici. Salviati cura la rassettatura del <b>Decameron</b>, una censura morale che stimola, per paradosso, l'attenzione filologica. Dopo Salviati gli accademici lavorano con rigore e collegialità, si autofinanziano e hanno relativa libertà dalle autorità. Il <b>Vocabolario</b> esce nel <b>1612</b> a Venezia, con il <b>frullone</b> che separa la farina dalla crusca. Fedele a Salviati, documenta la continuità tra toscano vivo e trecentesco, con autori antichi anche minori, in chiave antibembiana.",
   ["La Crusca nasce nel <b>1582</b> come gioco e diventa filologica con <b>Salviati</b>.",
    "Gli accademici lavorano con rigore e collegialità e pubblicano nel <b>1612</b> il <b>Vocabolario</b>.",
    "Il Vocabolario documenta la continuità tra toscano vivo e trecentesco, in chiave antibembiana."]),
  ("5.5 La Realtà Povera dell'Italiano: Scritture dei Semicolti", None,
   "Fuori dalla letteratura, nelle scritture pratiche, nel Cinquecento cresce l'uso dell'italiano, a volte da parte di persone di scarsa cultura. L'analfabetismo era diffuso nelle campagne, ma nelle città, soprattutto a Roma, c'erano popolani capaci di leggere e scrivere, come mostra <b>Petrucci</b> con il <b>quaderno di Maddalena</b>. Forme ibride compaiono in diari, libri di famiglia, quaderni e lettere comuni, utili per verificare la diffusione del modello toscano letterario a livello medio. Una lettera del <b>1582</b> da Claro è satura di forme dialettali settentrionali e di sintassi malgovernata; altre, come quella del <b>1599</b> sulla peste, hanno un livello più alto, con ipercorrettismi. Anche i libri a stampa (libri di segreti, ricettari, trattati di dietetica) offrono un italiano extraletterario, con terminologia tecnica estranea all'italiano poetico.",
   ["Nel Cinquecento l'italiano si diffonde anche nelle scritture pratiche, a volte di persone poco colte.",
    "Diari, lettere e quaderni mostrano forme ibride, con dialettalismi e ipercorrettismi, e permettono di misurare la diffusione del modello toscano.",
    "Anche ricettari e libri di segreti offrono un italiano tecnico, lontano da quello poetico."]),
  ("5.6 Precisazioni su Bembo, Grammatiche, Lessicografia e Chiesa", None,
   "Bembo, replicando a <b>Ercole Strozzi</b>, osserva che non c'è motivo di adottare una lingua che gli stessi autori classici avevano scacciata dalle loro scritture; riconosce che i toscani sono avvantaggiati nella conversazione, ma il suo trattato riguarda la nobile lingua della letteratura, regolata sul binomio Virgilio-Cicerone per il latino e <b>Petrarca</b>-<b>Boccaccio</b> per il volgare, con riserve su <b>Dante</b> per il suo eccesso di realismo. Fortunio non ha le riserve bembiane sul linguaggio di Dante. In lessicografia, il vocabolario di <b>Acarisio</b> (<b>1543</b>) precede La fabrica del mondo di <b>Alunno</b> (<b>1548</b>), il più noto della prima metà del secolo. Il modello toscano uniforme agisce soprattutto sugli scriventi colti. Salviati si forma rassettando il <b>Decameron</b>, nel clima della <b>Controriforma</b>, e il giudizio su Dante risente delle stesse ragioni. Nei paesi riformati i testi sacri sono letti dal comune fedele; nei paesi cattolici la liturgia mantiene il latino fino al <b>1965</b>.",
   ["Bembo difende il volgare letterario, regolato sul binomio <b>Petrarca</b>-<b>Boccaccio</b>, con riserve su <b>Dante</b>.",
    "La lessicografia della prima metà del secolo ha in <b>Alunno</b> il suo vocabolario più noto.",
    "La <b>Controriforma</b> condiziona Salviati e la Chiesa cattolica mantiene il latino nella liturgia fino al <b>1965</b>, a differenza dei paesi riformati."]),
 ], ["<b>Collegamenti da ricordare:</b> koinè quattrocentesca → Manuzio e Bembo → grammatiche → Accademie → Crusca (<b>1612</b>) → opposizioni di Beni e Tassoni (Cap. 6)."]*2),
]
